          "quoteZh": "《大唐西域记》：“缚喝国，伽蓝百有余所，僧徒三千余人。”",
          "quoteEn": "Great Tang Records: \"The Kingdom of Balkh has over a hundred monasteries and more than three thousand monks.\"",
