          "titleEn": "Magistrate of Luling — Benevolent Governance",
          "descZh": "刘瑾伏诛前夕，守仁升任江西吉安府庐陵县知县。视事七月，不以威刑而重告谕，均徭役、息词讼、立十家牌保甲法，选里老敦厚者劝诫乡民，庐陵风俗翕然丕变，为日后经略江西奠定深厚民心。",
